function reviewTargetSharingStatus(n){const r=n.targetSharingReceipt;return r?`私人源档案 · 上次目标服务回执：${r.visibility==='public'?'公开展示':'已撤回展示'} v${r.sourceVersion}${r.sourceVersion!==n.version?'；当前修订未公开':''}`:'私人源档案 · 尚无目标公开回执'}
function reviewTargetSharingLabel(n){return n.targetSharingReceipt?.visibility==='public'?'审阅 / 撤回目标公开':'选择公开目标'}
async function reviewOpenTargetSharing(nid){const context=reviewContext(),n=S.nodes.find(n=>n.id===nid);if(!n||!S.user?.reviewService)return;const fingerprint=reviewSharedTarget(n);
 try{if(!reviewReady)throw Error('请先连接本人服务账号。');if(!save())throw Error('本机保存未完成，请保留目标后再核对。');await reviewFlush();const plan=await reviewKnowledgeRequest('/api/review-target-sharing?nodeId='+encodeURIComponent(nid),{context});if(!reviewContextCurrent(context)||reviewSharedTarget(S.nodes.find(n=>n.id===nid))!==fingerprint)throw Error('目标或账号已变化，请重新核对。');
  modal(`<h2>核对目标公开范围</h2><p class="small muted">只展示以下目标定义和本人作者身份，个人持有权保留。原私人版本留在本人档案；教程、笔记、实践与证据不会随目标公开。捐赠为另一项归属操作。</p><h3 style="margin-top:16px">${esc(plan.target.title)} · v${plan.target.version}</h3><p class="pre">${esc(plan.target.goal)}</p><p class="pre small">五分钟起步：${esc(plan.target.five)}</p><p class="small muted">${esc(plan.target.domain)} / ${esc(plan.target.branch)}</p><p>${plan.current?.visibility==='public'?'服务当前正在公开展示这个目标。':'服务当前没有公开展示这个目标。'}</p><form id="review-target-sharing-form" class="stack"><label class="field">本次操作<select name="action" aria-label="目标公开操作"><option value="publish">公开上述当前目标定义</option>${plan.current?'<option value="withdraw">撤回服务目标展示</option>':''}</select></label><label class="check-row"><input name="consent" type="checkbox" required>我明确确认以上展示范围或撤回选择</label><p id="review-target-sharing-error" class="error" role="alert"></p><button class="primary">确认本次目标操作</button></form><div class="row actions">${btn('重新核对','share-node:'+nid,'ghost')}${btn('暂不操作','dialog-close','ghost')}</div>`,'','目标公开核对');
  const form=document.getElementById('review-target-sharing-form');form.addEventListener('submit',async ev=>{ev.preventDefault();if(form.dataset.busy)return;form.dataset.busy='true';const button=form.querySelector('button');button.disabled=true;try{if(!form.isConnected||!reviewContextCurrent(context)||reviewSharedTarget(S.nodes.find(n=>n.id===nid))!==fingerprint)throw Error('目标或账号已变化，请重新核对。');const f=new FormData(form);if(!f.has('consent'))throw Error('请明确确认本次展示范围。');if(!save())throw Error('本机保存未完成。');await reviewFlush();const result=await reviewKnowledgeRequest('/api/review-target-sharing',{context,headers:{'If-Match':reviewClient.snapshot().revision,...(plan.revision?{'If-Target-Match':plan.revision}:{})},body:{nodeId:nid,sourceVersion:plan.target.version,action:f.get('action'),consent:true}});if(!reviewContextCurrent(context))return;const current=S.nodes.find(n=>n.id===nid);if(current){current.targetSharingReceipt={nodeId:result.node.id,treeId:result.node.treeId,visibility:result.node.visibility,sourceVersion:result.node.sourceVersion,version:result.node.version,revision:result.revision,at:Date.now()};save()}if(form.isConnected)closeModal();render(false);toast(result.node.visibility==='public'?'目标定义已公开展示，私人内容保留。':'目标展示已撤回，私人版本保留。')}catch(error){if(reviewContextCurrent(context)&&form.isConnected)document.getElementById('review-target-sharing-error').textContent=error.message}finally{delete form.dataset.busy;button.disabled=false}});
 }catch(error){if(reviewContextCurrent(context))modal(`<h2>目标公开尚未核对</h2><p>${esc(error.message)}</p><p class="small muted">需要先保存本人私人目标的当前版本到服务；原目标和填写内容保留。</p><div class="row actions">${btn('核对私人目标保存','review-private-target:'+nid)}${btn('稍后再做','dialog-close','ghost')}</div>`,'','目标公开状态')}
}
